// Use unsigned to avoid signed modulo edge semantics; template should accept it
using T = unsigned int;
T a = (T)*FUZZ_PARAM(unsigned int);
T b = (T)*FUZZ_PARAM(unsigned int);
T g = tcnn::gcd(a, b);
// Properties: gcd(0,0) == 0; gcd(a,0) == a; gcd divides both
if (a == 0 && b == 0) {
    FUZZ_ASSERT(g == 0, "gcd(0,0) must be 0");
} else {
    if (b == 0) { FUZZ_ASSERT(g == a, "gcd(a,0) must be a"); }
    if (a == 0) { FUZZ_ASSERT(g == b, "gcd(0,b) must be b"); }
    // g must divide both a and b (if non-zero)
    if (g != 0) {
        FUZZ_ASSERT(a % g == 0, "g must divide a");
        FUZZ_ASSERT(b % g == 0, "g must divide b");
    }
}

