using T = uint32_t;
T val = (T)(*FUZZ_PARAM(uint32_t) & 0x7FFFFFFFu);
T divisor = (T)((*FUZZ_PARAM(uint32_t) % 1024u) + 1u); // enforce non-zero, small divisor
T q = tcnn::div_round_up(val, divisor);
// Property: (q-1)*divisor < val <= q*divisor, except when val==0 then q==0
if (val == 0) {
    FUZZ_ASSERT(q == 0, "div_round_up(0, d) must be 0");
} else {
    FUZZ_ASSERT(q >= 1, "quotient must be at least 1 for val>0");
    FUZZ_ASSERT((T)((q - 1) * divisor) < val, "lower bound property failed");
    FUZZ_ASSERT((T)(q * divisor) >= val, "upper bound property failed");
}

using T = uint32_t;
T val = (T)(*FUZZ_PARAM(uint32_t) & 0x7FFFFFFFu);
T divisor = (T)((*FUZZ_PARAM(uint32_t) % 1024u) + 1u); // enforce non-zero
T nm = tcnn::next_multiple(val, divisor);
// Properties: nm is a multiple of divisor, nm >= val, and nm < val + divisor unless overflow wraps
FUZZ_ASSERT(nm % divisor == 0, "next_multiple must return a multiple of divisor");
FUZZ_ASSERT(nm >= val, "next_multiple must be >= val");
if (0xFFFFFFFFu - val >= divisor) { // avoid wrap check when overflow possible
    FUZZ_ASSERT(nm < val + divisor, "next_multiple must be the next multiple (strictly less than val+divisor)");
}

