uint32_t v = (uint32_t)*FUZZ_PARAM(uint32_t);
uint32_t np = tcnn::next_pot(v);
if (v == 0u) {
    FUZZ_ASSERT(np == 0u, "next_pot(0) must be 0");
} else {
    // Must be a power of two and >= v
    FUZZ_ASSERT((np & (np - 1u)) == 0u, "next_pot must return a power of two");
    FUZZ_ASSERT(np >= v, "next_pot must be >= v");
    // Previous power of two is np>>1; must be < v (unless v itself is a power of two)
    if ((v & (v - 1u)) != 0u) {
        FUZZ_ASSERT((np >> 1) < v, "next_pot must be the next higher power of two for non-powers");
    }
}

